import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class ContractTest{static final class Item implements Comparable<Item>{final int value;Item(int v){value=v;}public int compareTo(Item x){return Integer.compare(value,x.value);}} @Test void tiedIdentityAndSourcePreserved(){Item a=new Item(2),b=new Item(2),low=new Item(-1);Item[]in={low,a,b};Item[]copy=in.clone();Item result=TaskBinding.maximum(in,0,3);assertTrue(result==a||result==b);assertArrayEquals(copy,in);assertEquals(-3,TaskBinding.maximum(new Integer[]{-9,-3,-4},0,3));}}
